#4.1) Two pops: Pop. split - 250

def popSplit(initialSize, splitSize, splitTime):
    demoSplit = msprime.Demography()
    demoSplit.add_population (name='popA', initial_size=splitSize)
    demoSplit.add_population (name='popB', initial_size=splitSize)
    demoSplit.add_population (name='popAB', initial_size=initialSize)
    demoSplit.add_population_split (time=splitTime, derived=["popA", "popB"], ancestral="popAB")
    return demoSplit

#5) Stepping stone
def isValidDeme(deme, dim):
    """
    Checks whether the given deme is within the boundaries.
    """
    (n, m) = dim
    (i, j) = deme
    isValid = True
    isValid &= ((i >= 0) and (i < n))
    isValid &= ((j >= 0) and (j < m))
    return isValid


# %%
def stepping_stone2d (meta_size, migRate, treeSeq = None):
    """
    sets up a demographic model representing a 2D stepping-stone model
    """
    assert len(meta_size.shape) == 2
    n, m = meta_size.shape

    # just double check
    if ((n == 1) and (m == 1)):
        assert (migRate is None)
    else:
        assert (migRate is not None)
    # fill it in an order where column index j increases fastest until m
    idxToDeme = {}
    # but it starts at 1 because of slim
    currIdx = 1
    for i in range(n):
        for j in range (m):
            idxToDeme[currIdx] = (i,j)
            currIdx += 1

    # the inverse map
    demeToIdx = {}
    for (thisIdx, thisPair) in idxToDeme.items():
        # make sure it matches what we used in SLiM
        assert (thisPair[0]*m + thisPair[1] + 1 == thisIdx)
        demeToIdx[thisPair] = thisIdx

    # we need one bogus population to emulate slim
    if (treeSeq is None):
        demography = msprime.Demography.isolated_model (np.concatenate (([1], meta_size.reshape(n*m))))
        # AS LONG AS THE SECOND INDEX INCREASES FASTER, THE ORDERING OF THE SIZES IS CORRECT
    else:
        # need to initialize from treeSeq, so the populations match
        demography = msprime.Demography.from_tree_sequence(treeSeq)
        for pop in demography.populations:
            # must set their effective population sizes
            if (pop.id < 1):
                # this one is bogus (who knows why SLiM puts it here)
                pop.initial_size = 1
            else:
                # real population
                thisPair = idxToDeme[pop.id]
                pop.initial_size = meta_size[thisPair[0],thisPair[1]]

    # still need to put in migration rates
    migMatrix = demography.migration_matrix
    # iterate over source demes
    # for srcIdx in range(M.shape[0]):
    # this is all due to SLiM, because there is one empty pop in the beginning
    for srcIdx in range(1,migMatrix.shape[0]):
        srcDeme = idxToDeme[srcIdx]
        (srcI, srcJ) = srcDeme
        # don't rename
        # demography.populations[srcIdx].name = f"pop_{srcI}_{srcJ}"
        # print(srcDeme)

        # where can we go from here
        dstDemes = [
            (srcI + 1, srcJ),
            (srcI - 1, srcJ),
            (srcI, srcJ + 1),
            (srcI, srcJ - 1),
        ]
        for dstDeme in dstDemes:
            if isValidDeme(dstDeme, (n,m)):
                # print(f"--> {dstDeme}")
                assert (migRate is not None)
                migMatrix[demeToIdx[srcDeme], demeToIdx[dstDeme]] = migRate
            # else:
                # print(f"-x> {(dstDeme[0] % n, dstDeme[1] % m)}")

    return (demography, idxToDeme, demeToIdx)
meta_size = np.ones((9,9))*500
#5.1-5.3
(demoStep05, idxToDeme1, demeToIdx1) = stepping_stone2d(meta_size,0.05)
(demoStep005, idxToDeme2, demeToIdx2) = stepping_stone2d(meta_size,0.005)
(demoStep0005, idxToDeme3, demeToIdx3) = stepping_stone2d(meta_size,0.0005)

demoSplit500 = popSplit(10000,5000,500)
demoSplit1000 = popSplit(10000,5000,1000)
demoSplit2000 = popSplit(10000,5000,2000)

#6
species = stdpopsim.get_species("HomSap")
demoOOA = species.get_demographic_model("OutOfAfrica_3G09").model

deme_list = [demoConst, demoExp, demoSplit500, demoSplit1000, demoSplit2000, demoStep05, demoStep005, demoStep0005, demoOOA, demoBottleneck]
demo_names = ["const", "exp", "split_500", "split_1000", "split_2000", "step_05","step_005","step_0005","out_of_africa","bottleneck_2000"]
L = 1e8


for i in range(j,j+1):
    os.makedirs(f'official_data2/diploid_sim/{demo_names[i]}', exist_ok=True)
    os.makedirs('official_data2/diploid_sim/trees', exist_ok=True)
    if (i in range(2,5)):
        samples = {"popA": 50, "popB": 50}
    elif i == 5:
        demestoSample = [(0,0),(0,8),(8,0),(8,8),(4,4)]
        idx_list = [demeToIdx1[deme] for deme in demestoSample]
        samples = {f"pop_{num}": 20 for num in idx_list}
    elif i == 6:
        demestoSample = [(0,0),(0,8),(8,0),(8,8),(4,4)]
        idx_list = [demeToIdx2[deme] for deme in demestoSample]
        samples = {f"pop_{num}": 20 for num in idx_list}
    elif i == 7:
        demestoSample = [(0,0),(0,8),(8,0),(8,8),(4,4)]
        idx_list = [demeToIdx3[deme] for deme in demestoSample]
        samples = {f"pop_{num}": 20 for num in idx_list}
    elif i == 8:
        samples = {"YRI": 50, "CEU": 50, "CHB":50}
    else:
        samples = {"popA": 100}

    simple_demo = msprime.sim_ancestry(
        demography=deme_list[i],
        samples=samples,
        sequence_length=L,
        recombination_rate=1.25e-8,
        random_seed=metarng.integers(999999999),
    )
    

    #Compare ground truth sim with SINGER reconstruction
    mutated = msprime.sim_mutations(simple_demo, rate=1.25e-8, random_seed=metarng.integers(999999999))
    vcf_path = f'official_data2/diploid_sim/{demo_names[i]}/{demo_names[i]}.vcf'
    #rename individuals to include their population index (denoted by DIdx1_DIdx2 for the stepping stone model)
    if i in range(5,8):
        individualNames = []
        indCounter = 0
        for ind in mutated.individuals():
            idxToDeme_list = [idxToDeme1, idxToDeme2, idxToDeme3]
            thisDeme = idxToDeme_list[i-5][mutated.nodes_population[ind.nodes[0]]]
            thisName = f"tsk_D{thisDeme[0]}_D{thisDeme[1]}_{indCounter}"
            individualNames.append (thisName)
            indCounter += 1
    else:
        individualNames = []
        indCounter = 0
        for ind in mutated.individuals():
            thisPop = mutated.nodes_population[ind.nodes[0]]
            popMeta = mutated.population(thisPop).metadata
            # metadata may come back as a dict already, or as raw bytes/JSON
            if isinstance(popMeta, bytes):
                popMeta = json.loads(popMeta.decode())
            popName = popMeta.get("name", str(thisPop))
            thisName = f"tsk_D{popName}_{indCounter}"
            individualNames.append (thisName)
            indCounter += 1
    #Write vcf including newly created individual names
    with open(vcf_path, 'w') as vcf_file:
        mutated.write_vcf(vcf_file, individual_names=individualNames)
    tszip.compress(mutated, f"official_data2/diploid_sim/trees/{demo_names[i]}.trees.tsz")
